  async function init(){if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('/sw.js').catch(()=>{});const requestedPage=new URLSearchParams(location.search).get('page');const initialPage=validPages.has(requestedPage)?requestedPage:'feed';if(!db){closeAuth();await loadFeed();showPage('feed');return}const {data:{session}}=await db.auth.getSession();if(session){user=session.user;await loadProfile();closeAuth();await loadFeed();showPage(initialPage)}else{closeAuth();await loadFeed();showPage('feed')}db.auth.onAuthStateChange(async(_event,session)=>{user=session?.user||null;if(user){await loadProfile();closeAuth();await loadFeed();const target=validPages.has(new URLSearchParams(location.search).get('page'))?new URLSearchParams(location.search).get('page'):'feed';showPage(target)}else{profile=null;updateAccount();closeAuth();await loadFeed();showPage('feed')}})}
